<?php\n\nuse App\Models\Company;\nuse App\Models\Section;\nuse App\Models\User;\nuse App\Models\Delivery;\nuse App\Models\DeliveryRoute;\nuse Illuminate\Foundation\Testing\RefreshDatabase;\n\nuses(RefreshDatabase::class);\n\ntest('malibo delivery creation without vat', function () {\n    $company = Company::factory()->create(['company_code' => 'MAL001']);\n    $user = User::factory()->create(['company_code' => 'MAL001']);\n    $section = Section::factory()->create([\n        'company_code' => 'MAL001',\n        'is_main_stock' => false,\n        'section_type' => 'warehouse'\n    ]);\n    \n    $deliveryRoute = DeliveryRoute::factory()->create([\n        'company_code' => 'MAL001'\n    ]);\n    \n    $this->actingAs($user);\n    \n    $response = $this->postJson('/malibo/deliveries', [\n        'delivery_route_id' => $deliveryRoute->id,\n        'customer_name' => 'ABC Store',\n        'customer_address' => '123 Main Street, Colombo',\n        'customer_phone' => '0112345678',\n        'items' => [\n            [\n                'item_name' => 'Business Cards',\n                'quantity' => 1000,\n                'unit_price' => 0.50,\n                'total_price' => 500.00\n            ]\n        ],\n        'total_amount' => 500.00,\n        // Note: No VAT fields for MALIBO operations\n        'delivery_date' => now()->addDay()->format('Y-m-d'),\n        'priority' => 'normal'\n    ]);\n    \n    $response->assertStatus(201);\n    $response->assertJsonStructure([\n        'data' => [\n            'id',\n            'delivery_number',\n            'customer_name',\n            'total_amount',\n            'status'\n        ]\n    ]);\n    \n    // Verify no VAT fields in response\n    expect($response->json('data'))->not->toHaveKey('vat_amount');\n    expect($response->json('data'))->not->toHaveKey('vat_rate');\n});\n\ntest('malibo delivery route optimization', function () {\n    $company = Company::factory()->create(['company_code' => 'MAL001']);\n    $user = User::factory()->create(['company_code' => 'MAL001']);\n    \n    $deliveryRoute = DeliveryRoute::factory()->create([\n        'company_code' => 'MAL001',\n        'route_name' => 'Colombo Central Route',\n        'is_active' => true\n    ]);\n    \n    // Create multiple deliveries for the route\n    $deliveries = [];\n    for ($i = 1; $i <= 5; $i++) {\n        $deliveries[] = Delivery::factory()->create([\n            'delivery_route_id' => $deliveryRoute->id,\n            'company_code' => 'MAL001',\n            'customer_address' => \"Address {$i}\",\n            'status' => 'pending'\n        ]);\n    }\n    \n    $this->actingAs($user);\n    \n    $response = $this->postJson(\"/malibo/routes/{$deliveryRoute->id}/optimize\", [\n        'optimization_criteria' => 'distance',\n        'start_location' => 'Warehouse, Colombo 5',\n        'max_stops_per_trip' => 3\n    ]);\n    \n    $response->assertStatus(200);\n    $response->assertJsonStructure([\n        'data' => [\n            'optimized_route' => [\n                'total_distance',\n                'estimated_time',\n                'stops' => []\n            ]\n        ]\n    ]);\n});\n\ntest('malibo printing stock management', function () {\n    $company = Company::factory()->create(['company_code' => 'MAL001']);\n    $user = User::factory()->create(['company_code' => 'MAL001']);\n    $printingSection = Section::factory()->create([\n        'company_code' => 'MAL001',\n        'section_code' => 'PRINT001',\n        'is_main_stock' => false,\n        'section_type' => 'store'\n    ]);\n    \n    $this->actingAs($user);\n    \n    // Check printing stock\n    $response = $this->getJson('/malibo/printing/stock', [\n        'section_code' => $printingSection->section_code\n    ]);\n    \n    $response->assertStatus(200);\n    $response->assertJsonStructure([\n        'data' => [\n            'stocks' => [],\n            'summary' => [\n                'total_items',\n                'low_stock_items',\n                'out_of_stock_items'\n            ]\n        ]\n    ]);\n});\n\ntest('malibo printer transfer between sections', function () {\n    $company = Company::factory()->create(['company_code' => 'MAL001']);\n    $user = User::factory()->create(['company_code' => 'MAL001']);\n    \n    $sourceSection = Section::factory()->create([\n        'company_code' => 'MAL001',\n        'section_code' => 'PRINT001',\n        'is_main_stock' => false\n    ]);\n    \n    $targetSection = Section::factory()->create([\n        'company_code' => 'MAL001',\n        'section_code' => 'PRINT002',\n        'is_main_stock' => false\n    ]);\n    \n    $this->actingAs($user);\n    \n    $response = $this->postJson('/malibo/printing/transfers', [\n        'from_section_code' => $sourceSection->section_code,\n        'to_section_code' => $targetSection->section_code,\n        'items' => [\n            [\n                'item_code' => 'PAPER_A4',\n                'item_name' => 'A4 Paper - White',\n                'quantity' => 50,\n                'unit_cost' => 2.50,\n                'transfer_type' => 'printing_supply'\n            ]\n        ],\n        'reason' => 'Stock redistribution for printing jobs',\n        'requested_by' => $user->id\n    ]);\n    \n    $response->assertStatus(201);\n    \n    // Verify transfer record\n    $this->assertDatabaseHas('stock_transfers', [\n        'from_section_code' => $sourceSection->section_code,\n        'to_section_code' => $targetSection->section_code,\n        'type' => 'printing_transfer',\n        'status' => 'pending_approval'\n    ]);\n});\n\ntest('malibo barcode generation for products', function () {\n    $company = Company::factory()->create(['company_code' => 'MAL001']);\n    $user = User::factory()->create(['company_code' => 'MAL001']);\n    \n    $this->actingAs($user);\n    \n    $response = $this->postJson('/malibo/printing/barcodes/generate', [\n        'items' => [\n            [\n                'item_code' => 'CARD001',\n                'item_name' => 'Business Card Template',\n                'batch_no' => 'BC2024001',\n                'quantity' => 100\n            ]\n        ],\n        'barcode_type' => 'CODE128',\n        'print_format' => 'label_sheet',\n        'include_text' => true\n    ]);\n    \n    $response->assertStatus(200);\n    $response->assertJsonStructure([\n        'data' => [\n            'batch_id',\n            'generated_count',\n            'download_url',\n            'expires_at'\n        ]\n    ]);\n});\n\ntest('malibo delivery tracking and status updates', function () {\n    $company = Company::factory()->create(['company_code' => 'MAL001']);\n    $user = User::factory()->create(['company_code' => 'MAL001']);\n    \n    $delivery = Delivery::factory()->create([\n        'company_code' => 'MAL001',\n        'status' => 'pending'\n    ]);\n    \n    $this->actingAs($user);\n    \n    // Update delivery status\n    $response = $this->patchJson(\"/malibo/deliveries/{$delivery->id}/status\", [\n        'status' => 'in_transit',\n        'notes' => 'Driver has picked up the order',\n        'location' => 'Warehouse - Colombo 5',\n        'updated_by' => $user->id\n    ]);\n    \n    $response->assertStatus(200);\n    \n    // Verify status update\n    $this->assertDatabaseHas('deliveries', [\n        'id' => $delivery->id,\n        'status' => 'in_transit'\n    ]);\n    \n    // Check tracking information\n    $trackingResponse = $this->getJson(\"/malibo/deliveries/{$delivery->id}/tracking\");\n    \n    $trackingResponse->assertStatus(200);\n    $trackingResponse->assertJsonStructure([\n        'data' => [\n            'delivery_id',\n            'current_status',\n            'tracking_history' => [],\n            'estimated_delivery',\n            'current_location'\n        ]\n    ]);\n});\n\ntest('malibo customer management without vat registration', function () {\n    $company = Company::factory()->create(['company_code' => 'MAL001']);\n    $user = User::factory()->create(['company_code' => 'MAL001']);\n    \n    $this->actingAs($user);\n    \n    $response = $this->postJson('/malibo/customers', [\n        'name' => 'Quick Print Shop',\n        'contact_person' => 'Ravi Silva',\n        'phone' => '0114567890',\n        'email' => 'ravi@quickprint.lk',\n        'address' => '456 Galle Road, Mount Lavinia',\n        'customer_type' => 'business',\n        // Note: No VAT registration fields for MALIBO\n        'credit_limit' => 50000.00,\n        'payment_terms' => '30_days'\n    ]);\n    \n    $response->assertStatus(201);\n    $response->assertJsonStructure([\n        'data' => [\n            'id',\n            'name',\n            'contact_person',\n            'phone',\n            'address',\n            'customer_type'\n        ]\n    ]);\n    \n    // Verify no VAT-related fields\n    expect($response->json('data'))->not->toHaveKey('vat_number');\n    expect($response->json('data'))->not->toHaveKey('tax_registration');\n});\n\ntest('malibo distribution performance reports', function () {\n    $company = Company::factory()->create(['company_code' => 'MAL001']);\n    $user = User::factory()->create(['company_code' => 'MAL001']);\n    \n    $this->actingAs($user);\n    \n    $response = $this->getJson('/malibo/reports/distribution', [\n        'date_from' => now()->subMonth()->format('Y-m-d'),\n        'date_to' => now()->format('Y-m-d'),\n        'include_routes' => true,\n        'include_performance_metrics' => true\n    ]);\n    \n    $response->assertStatus(200);\n    $response->assertJsonStructure([\n        'data' => [\n            'summary' => [\n                'total_deliveries',\n                'completed_deliveries',\n                'pending_deliveries',\n                'success_rate'\n            ],\n            'route_performance' => [],\n            'delivery_trends' => []\n        ]\n    ]);\n});